import json, urllib.request as u
URL = 'http://127.0.0.1:49374/mcp'
def rpc(i, method, params, sid=None):
    h = {'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream'}
    if sid:
        h['Mcp-Session-Id'] = sid
    body = {'jsonrpc': '2.0', 'method': method, 'params': params}
    if i is not None:
        body['id'] = i
    r = u.urlopen(u.Request(URL, data=json.dumps(body).encode(), headers=h, method='POST'), timeout=120)
    t = r.read().decode()
    return r.headers.get('Mcp-Session-Id') or sid, (json.loads(t) if t.strip() else None)
sid, init = rpc(1, 'initialize', {'protocolVersion': '2025-03-26', 'capabilities': {}, 'clientInfo': {'name': 'nas-receipt-probe', 'version': '0'}})
rpc(None, 'notifications/initialized', {}, sid)
_, tl = rpc(2, 'tools/list', {}, sid)
names = sorted(t['name'] for t in tl['result']['tools'])
_, st = rpc(3, 'tools/call', {'name': 'memory_status', 'arguments': {'workspace': 'personal', 'project': 'agent-ecosystem'}}, sid)
res = st['result']
text = ''.join(c.get('text', '') for c in res.get('content', []) if c.get('type') == 'text')
try:
    body = json.loads(text)
except ValueError:
    body = {}
counts = body.get('counts') or {k: body.get(k) for k in ('pages', 'sessions', 'observations') if k in body}
_, mq = rpc(4, 'tools/call', {'name': 'memory_query', 'arguments': {'query': 'first backup', 'workspace': 'personal', 'project': 'agent-ecosystem'}}, sid)
qres = mq['result']
try:
    hits = json.loads(''.join(c.get('text', '') for c in qres.get('content', []) if c.get('type') == 'text')).get('hits', [])
except ValueError:
    hits = []
print('server', init['result']['serverInfo'], '| tools', len(names), '| memory_status isError', res.get('isError', False), 'scope', body.get('scope', {}).get('resolved_by'), 'counts', counts, '| memory_query isError', qres.get('isError', False), 'hits', len(hits))
raise SystemExit(0 if not res.get('isError') and not qres.get('isError') and counts and hits else 1)
